import type { ReactNode } from "react";

/** Internal layout shared by domain panels. Shipped with its owning component. */
export function PanelHeader({
  icon,
  title,
  description,
  status,
  action,
  as: Heading = "h3",
}: {
  icon: ReactNode;
  title: string;
  description?: ReactNode;
  status?: ReactNode;
  action?: ReactNode;
  as?: "h2" | "h3";
}) {
  return (
    <div data-slot="panel-header" className="min-w-0">
      <div
        data-slot="panel-topline"
        className="grid min-w-0 grid-cols-[minmax(0,1fr)_auto] items-start gap-x-3 gap-y-2"
      >
        <div
          data-slot="panel-identity"
          className="flex min-w-0 items-start gap-3"
        >
          <span
            data-slot="panel-icon"
            aria-hidden="true"
            className="surface-control grid size-10 shrink-0 place-items-center rounded-full border bg-secondary text-secondary-foreground shadow-sm [&>svg]:size-4"
          >
            {icon}
          </span>
          <div
            data-slot="panel-heading"
            className="flex min-h-12 min-w-0 flex-col"
          >
            <Heading
              data-slot="panel-title"
              className="text-base font-medium leading-snug wrap-anywhere"
            >
              {title}
            </Heading>
            {description && (
              <p
                data-slot="panel-description"
                className="mt-1 text-sm leading-relaxed text-muted-foreground wrap-anywhere"
              >
                {description}
              </p>
            )}
          </div>
        </div>
        {(status != null || action != null) && (
          <div
            data-slot="panel-meta"
            className="ml-auto flex min-w-0 flex-wrap items-center justify-end gap-2 text-right text-sm text-muted-foreground"
          >
            {status != null && (
              <div data-slot="panel-status" className="min-w-0 wrap-anywhere">
                {status}
              </div>
            )}
            {action}
          </div>
        )}
      </div>
    </div>
  );
}

import type { ComponentProps } from "react";
import { PanelHeader } from "@/components/iot/internal/panel-header";

type PanelProps = ComponentProps<typeof PanelHeader> &
  Omit<ComponentProps<"section">, "title"> & {
    contentClassName?: string;
  };

/** Owns the surface, all four insets, header alignment and the content boundary. */
export function Panel({
  icon,
  title,
  description,
  status,
  action,
  as,
  className = "",
  contentClassName = "",
  children,
  ...props
}: PanelProps) {
  return (
    <section
      data-slot="panel"
      data-panel-layout=""
      className={`@container surface-raised grid min-w-0 gap-[var(--card-padding,24px)] rounded-xl border bg-card p-[var(--card-padding,24px)] text-card-foreground shadow-sm ${className}`}
      {...props}
    >
      <PanelHeader
        icon={icon}
        title={title}
        description={description}
        status={status}
        action={action}
        as={as}
      />
      <div
        data-slot="panel-content"
        className={`min-w-0 ${contentClassName || "space-y-5"}`}
      >
        {children}
      </div>
    </section>
  );
}

import { Info } from "lucide-react";
import { Popover } from "radix-ui";
import {
  createTelemetryGeometry,
  formatAxisNumber,
  formatTelemetryNumber,
  telemetryWindowLabel,
  validDomain,
  validTimestamp,
  type NumericDomain,
  type TelemetryPoint,
  type TelemetryWindow,
} from "@/lib/telemetry";

export type TrendHistory = {
  points: TelemetryPoint[];
  /** Name the record type: observations, aggregates, estimates or predictions. */
  label: string;
  maxGapMs?: number;
  window?: TelemetryWindow;
  /** Use the same domain for adjacent, comparable sparklines. */
  domain?: NumericDomain;
};

/** Overview only; the same renderer is used by cards and catalog thumbnails. */
export function TelemetrySparkline({
  history,
  label,
  unit,
  precision = 1,
  compact = false,
}: {
  history: TrendHistory;
  label: string;
  unit: string;
  precision?: number;
  compact?: boolean;
}) {
  if (
    history.window &&
    (!validTimestamp(history.window.from) ||
      !validTimestamp(history.window.to) ||
      history.window.to < history.window.from)
  )
    return <p className="text-sm text-warning-text">历史时间窗口无效</p>;
  if (
    history.points.length &&
    !history.points.some((p) => validTimestamp(p.timestamp))
  )
    return <p className="text-sm text-warning-text">历史记录的时间均无效</p>;
  const geometry = createTelemetryGeometry(history.points, 400, 64, history);
  const { segments, min, max, from, to, hasGaps, dataMin, dataMax } = geometry;
  if (!segments.length)
    return (
      <p className="py-5 text-sm text-muted-foreground">
        {geometry.samples.length ? "历史记录均缺测或无效" : "暂无历史记录"}
      </p>
    );
  const count = segments.reduce((n, segment) => n + segment.length, 0);
  return (
    <figure className="space-y-2" data-slot="metric-trend">
      <div className="flex min-h-10 flex-wrap items-center justify-between gap-x-3 text-sm text-muted-foreground">
        <span>概览 · {unit || "无量纲"}</span>
        <Popover.Root>
          <Popover.Trigger asChild>
            <button
              type="button"
              className="inline-flex min-h-10 items-center gap-2 rounded-sm focus-visible:outline-2 focus-visible:outline-ring"
              aria-label={`趋势信息 · ${label}`}
            >
              <span>
                {!validDomain(history.domain) && "自动 "}
                {formatAxisNumber(min)}–{formatAxisNumber(max)}
              </span>
              <Info className="size-3.5" />
            </button>
          </Popover.Trigger>
          <Popover.Portal>
            <Popover.Content
              sideOffset={8}
              align="end"
              collisionPadding={12}
              aria-label="趋势信息"
              className="z-50 w-72 max-w-[calc(100vw-24px)] space-y-2 rounded-lg border border-border bg-popover p-4 text-sm text-popover-foreground shadow-lg"
            >
              <p className="font-medium">
                {history.label} · {count} 个读数
              </p>
              <p>
                {validDomain(history.domain) ? "参考范围" : "独立自动范围"}{" "}
                {formatAxisNumber(min)}–{formatAxisNumber(max)} {unit}
              </p>
              <p>
                最低 {formatTelemetryNumber(dataMin, precision)} · 最高{" "}
                {formatTelemetryNumber(dataMax, precision)} {unit}
              </p>
              <p className="text-muted-foreground">
                概览。{hasGaps && "含缺测。"}
                {geometry.samples.some((p) => p.quality === "estimated") &&
                  "□ 估算。"}
                {geometry.samples.some((p) => p.quality === "uncertain") &&
                  "◇ 存疑。"}
                精确样本见历史查询。
              </p>
            </Popover.Content>
          </Popover.Portal>
        </Popover.Root>
      </div>
      <svg
        viewBox="-4 0 408 80"
        preserveAspectRatio="none"
        role="img"
        aria-label={`${label}，${count} 个有效点，最低 ${formatTelemetryNumber(dataMin, precision)}，最高 ${formatTelemetryNumber(dataMax, precision)} ${unit}。${hasGaps ? "含缺测，断线不插值。" : ""}仅用于概览。`}
        className={`${compact ? "h-20" : "h-28"} block w-full text-chart-1`}
        data-slot="telemetry-plot"
      >
        {[8, 72].map((y) => (
          <path
            key={y}
            d={`M0 ${y}H400`}
            fill="none"
            stroke="currentColor"
            strokeOpacity=".12"
            vectorEffect="non-scaling-stroke"
          />
        ))}
        {segments.map((segment, i) =>
          segment.length === 1 ? (
            <circle
              key={i}
              cx={segment[0].x}
              cy={segment[0].y + 8}
              r="3"
              fill="currentColor"
            />
          ) : (
            <polyline
              key={i}
              points={segment.map((p) => `${p.x},${p.y + 8}`).join(" ")}
              fill="none"
              stroke="currentColor"
              strokeWidth="2.25"
              vectorEffect="non-scaling-stroke"
              strokeLinejoin="round"
              strokeLinecap="round"
            />
          ),
        )}
        {segments
          .flat()
          .filter(
            (p) =>
              p.point.quality === "estimated" ||
              p.point.quality === "uncertain",
          )
          .map((p) => (
            <rect
              key={p.point.timestamp}
              x={p.x - 3}
              y={p.y + 5}
              width="6"
              height="6"
              fill="var(--card)"
              stroke="currentColor"
              vectorEffect="non-scaling-stroke"
              transform={
                p.point.quality === "uncertain"
                  ? `rotate(45 ${p.x} ${p.y + 8})`
                  : undefined
              }
            />
          ))}
      </svg>
      <p className="text-sm tabular-nums text-muted-foreground">
        {telemetryWindowLabel(from, to)}
      </p>
      {history.domain && !validDomain(history.domain) && (
        <p className="text-sm text-warning-text">
          参考尺度无效，已使用自动尺度。
        </p>
      )}
      {geometry.expanded && (
        <figcaption className="text-sm text-warning-text">
          超出参考范围
        </figcaption>
      )}
    </figure>
  );
}

export type DataTone = "neutral" | "positive" | "warning" | "negative";
export type ScalarValue = number | string | boolean | null;
export type CardValue = ScalarValue | Record<string, ScalarValue>[];

type Identity = {
  id: string;
  label: string;
  subject: string;
  description?: string;
};
export type ScalarDefinition = Identity &
  (
    | {
        type: "number";
        unit: string;
        precision?: number;
        range?: {
          min: number;
          max: number;
          target?: { low: number; high: number };
        };
      }
    | {
        type: "state";
        states: { value: string | boolean; label: string; tone?: DataTone }[];
      }
    | { type: "text" }
  );
export type CardDefinition =
  | ScalarDefinition
  | (Identity & {
      type: "table";
      columns: {
        key: string;
        label: string;
        unit?: string;
        precision?: number;
      }[];
    });
export type MetricComparison = {
  label: string;
  referenceValue: number;
  mode: "absolute" | "relative" | "percentage-points";
  /** Assessment is supplied by the application, never inferred from direction. */
  tone?: DataTone;
};

export function comparisonValue(value: number, comparison: MetricComparison) {
  if (!Number.isFinite(value) || !Number.isFinite(comparison.referenceValue))
    return null;
  const difference = value - comparison.referenceValue;
  if (comparison.mode === "relative") {
    return comparison.referenceValue === 0
      ? null
      : (difference / Math.abs(comparison.referenceValue)) * 100;
  }
  return difference;
}

export function numberLabel(value: number, precision = 1) {
  if (!Number.isFinite(value)) return "—";
  const digits = Number.isFinite(precision)
    ? Math.max(0, Math.min(6, Math.trunc(precision)))
    : 1;
  return value.toLocaleString("en-US", {
    minimumFractionDigits: digits,
    maximumFractionDigits: digits,
  });
}

/** Keep full dates in metadata and allow wrapping only between date and clock. */
export function cardTimeParts(timestamp: number | null) {
  if (timestamp === null || !Number.isFinite(timestamp)) return null;
  const date = new Date(timestamp);
  if (!Number.isFinite(date.getTime())) return null;
  const iso = date.toISOString();
  return {
    date: iso.slice(0, 10),
    clock: timestamp % 1000 ? iso.slice(11, 23) : iso.slice(11, 19),
    iso,
  };
}

export function valueMatches(definition: CardDefinition, value: CardValue) {
  if (value === null) return false;
  if (definition.type === "number")
    return typeof value === "number" && Number.isFinite(value);
  if (definition.type === "text") return typeof value === "string";
  if (definition.type === "state")
    return definition.states.some((state) => state.value === value);
  return (
    Array.isArray(value) &&
    value.every(
      (row) => row !== null && typeof row === "object" && !Array.isArray(row),
    )
  );
}

"use client";

import { useEffect, useRef, useState, type ReactNode } from "react";
import {
  Activity,
  ArrowDownRight,
  ArrowUpRight,
  ChevronRight,
  History,
  Minus,
  Sigma,
} from "lucide-react";
import { Panel } from "@/components/iot/internal/panel";
import { Button } from "@/components/ui/button";
import { RangeGauge } from "@/components/iot/range-gauge";
import {
  TelemetrySparkline,
  type TrendHistory,
} from "@/components/iot/internal/telemetry-sparkline";
import {
  comparisonValue,
  cardTimeParts,
  numberLabel,
  valueMatches,
  type CardDefinition,
  type CardValue,
  type DataTone,
  type MetricComparison,
} from "@/components/iot/internal/data-card-model";

export type DataCardPresentation = {
  visualization?: "value" | "trend" | "range";
  history?: TrendHistory;
  comparison?: MetricComparison;
  secondary?: { label: string; value: string }[];
  historyHref?: string;
  loading?: boolean;
  error?: string;
};
const tones: Record<DataTone, string> = {
  neutral: "text-muted-foreground",
  positive: "text-success-text",
  warning: "text-warning-text",
  negative: "text-destructive",
};

export function DataTimestamp({ at }: { at: number | null }) {
  const parts = cardTimeParts(at);
  return parts ? (
    <time
      dateTime={parts.iso}
      className="inline-flex flex-wrap gap-x-1 tabular-nums"
    >
      <span className="whitespace-nowrap">{parts.date}</span>
      <span className="whitespace-nowrap">{parts.clock} UTC</span>
    </time>
  ) : (
    <span>时间未知</span>
  );
}

export function DataTimeWindow({ from, to }: { from: number; to: number }) {
  const start = cardTimeParts(from),
    end = cardTimeParts(to);
  if (!start || !end || to < from) return <span>统计窗口无效</span>;
  if (start.date === end.date)
    return (
      <span className="inline-flex flex-wrap gap-x-1 tabular-nums">
        <span className="whitespace-nowrap">{start.date}</span>
        <span className="whitespace-nowrap">{start.clock}</span>
        <span className="whitespace-nowrap">– {end.clock} UTC</span>
      </span>
    );
  return (
    <span className="flex flex-wrap items-baseline gap-x-2 gap-y-1">
      <DataTimestamp at={from} />
      <span>至</span>
      <DataTimestamp at={to} />
    </span>
  );
}

function ResultTable({
  definition,
  rows,
}: {
  definition: Extract<CardDefinition, { type: "table" }>;
  rows: Record<string, number | string | boolean | null>[];
}) {
  const wrapper = useRef<HTMLDivElement>(null);
  const [scrollable, setScrollable] = useState(false);
  useEffect(() => {
    const element = wrapper.current;
    if (!element) return;
    const measure = () =>
      setScrollable(element.scrollWidth > element.clientWidth + 1);
    const observer = new ResizeObserver(measure);
    observer.observe(element);
    if (element.firstElementChild) observer.observe(element.firstElementChild);
    measure();
    return () => observer.disconnect();
  }, []);
  const numericColumns = new Set(
    definition.columns
      .filter((column) => {
        const values = rows
          .map((row) => row[column.key])
          .filter((value) => value != null);
        return (
          column.precision != null ||
          (values.length > 0 &&
            values.every((value) => typeof value === "number"))
        );
      })
      .map((column) => column.key),
  );
  return (
    <div className="space-y-2">
      <div
        ref={wrapper}
        className="max-h-60 overflow-auto rounded-md border border-border"
        tabIndex={0}
        role="region"
        aria-label={`${definition.label}结果表`}
      >
        <table className="w-full text-left text-sm">
          <caption className="sr-only">
            {definition.label} · {definition.subject}
          </caption>
          <thead className="sticky top-0 z-10 bg-card text-muted-foreground">
            <tr>
              {definition.columns.map((column) => (
                <th
                  key={column.key}
                  scope="col"
                  className={`whitespace-nowrap px-3 py-2 font-medium ${numericColumns.has(column.key) ? "text-right" : ""}`}
                >
                  {column.label}
                  {column.unit && ` (${column.unit})`}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {rows.map((row, i) => (
              <tr key={i} className="border-t border-border">
                {definition.columns.map((column) => (
                  <td
                    key={column.key}
                    className={`whitespace-nowrap px-3 py-2 tabular-nums ${numericColumns.has(column.key) ? "text-right" : ""}`}
                  >
                    {row[column.key] == null ? (
                      <>
                        <span aria-hidden="true">—</span>
                        <span className="sr-only">无数据</span>
                      </>
                    ) : typeof row[column.key] === "number" ? (
                      column.precision == null ? (
                        Number.isFinite(row[column.key]) ? (
                          String(row[column.key])
                        ) : (
                          "—"
                        )
                      ) : (
                        numberLabel(row[column.key] as number, column.precision)
                      )
                    ) : (
                      String(row[column.key])
                    )}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {scrollable && (
        <p className="text-sm text-muted-foreground">左右滚动查看全部列</p>
      )}
    </div>
  );
}

/** Shared rendering within the two semantic cards; not a catalog component. */
export function DataCard({
  kind,
  definition,
  value,
  invalid = false,
  message,
  metadata,
  details,
  visualization = "value",
  history,
  comparison,
  secondary,
  historyHref,
  loading,
  error,
}: DataCardPresentation & {
  kind: "metric" | "indicator";
  definition: CardDefinition;
  value: CardValue;
  invalid?: boolean;
  message?: string;
  metadata: ReactNode;
  details: ReactNode;
}) {
  const available = !invalid && valueMatches(definition, value);
  const numeric =
    definition.type === "number" && available && typeof value === "number";
  const delta =
    numeric && comparison ? comparisonValue(value, comparison) : null;
  const state =
    definition.type === "state"
      ? definition.states.find((state) => state.value === value)
      : undefined;
  const outside =
    numeric &&
    definition.type === "number" &&
    definition.range &&
    Number.isFinite(definition.range.min) &&
    Number.isFinite(definition.range.max) &&
    definition.range.max > definition.range.min &&
    (value < definition.range.min || value > definition.range.max);
  return (
    <Panel
      data-slot={`${kind}-card`}
      className="data-card"
      icon={kind === "metric" ? <Activity /> : <Sigma />}
      title={definition.label}
      description={definition.subject}
      aria-busy={loading}
      action={
        historyHref && (
          <Button asChild variant="ghost" size="icon">
            <a href={historyHref} aria-label={`查看${definition.label}历史`}>
              <History aria-hidden="true" />
            </a>
          </Button>
        )
      }
    >
      <div className="space-y-4 wrap-anywhere">
        {loading ? (
          <p role="status" className="py-6 text-muted-foreground">
            正在读取{kind === "metric" ? "观测" : "计算结果"}…
          </p>
        ) : error ? (
          <p role="alert" className="py-6 text-destructive">
            {error}
          </p>
        ) : (
          <>
            {definition.type === "table" &&
            available &&
            Array.isArray(value) ? (
              value.length ? (
                <ResultTable definition={definition} rows={value} />
              ) : (
                <p className="py-5 text-muted-foreground">本次结果为空</p>
              )
            ) : (
              <div className="flex flex-wrap items-baseline gap-x-3 gap-y-2">
                <p
                  data-slot="data-card-value"
                  className={`flex max-w-full min-w-0 flex-wrap items-baseline gap-x-2 font-medium tracking-tight tabular-nums wrap-anywhere ${definition.type === "text" ? "text-xl" : "text-4xl"} ${available && state?.tone ? tones[state.tone] : ""}`}
                >
                  <span
                    className={
                      definition.type === "number"
                        ? "block max-w-full overflow-x-auto overflow-y-hidden whitespace-nowrap leading-[1.35]"
                        : ""
                    }
                    style={
                      numeric &&
                      numberLabel(value, definition.precision).length > 12
                        ? {
                            fontSize: `clamp(1rem, ${160 / numberLabel(value, definition.precision).length}cqi, 2.25rem)`,
                          }
                        : undefined
                    }
                  >
                    {!available
                      ? "—"
                      : definition.type === "number"
                        ? numberLabel(value as number, definition.precision)
                        : state
                          ? state.label
                          : value === ""
                            ? "空文本"
                            : String(value)}
                  </span>
                  {definition.type === "number" && (
                    <span className="whitespace-nowrap text-base font-normal tracking-normal text-muted-foreground">
                      {definition.unit}
                    </span>
                  )}
                </p>
                {numeric && comparison && (
                  <div
                    className={`flex min-w-0 max-w-full flex-wrap items-baseline gap-x-2 gap-y-1 text-sm tabular-nums ${tones[comparison.tone ?? "neutral"]}`}
                  >
                    <span className="inline-flex max-w-full items-center gap-1">
                      {delta !== null &&
                        (delta > 0 ? (
                          <ArrowUpRight
                            className="size-4 shrink-0"
                            aria-hidden="true"
                          />
                        ) : delta < 0 ? (
                          <ArrowDownRight
                            className="size-4 shrink-0"
                            aria-hidden="true"
                          />
                        ) : (
                          <Minus
                            className="size-4 shrink-0"
                            aria-hidden="true"
                          />
                        ))}
                      <span className="min-w-0 overflow-x-auto whitespace-nowrap">
                        {delta === null
                          ? "无法比较"
                          : `${delta > 0 ? "+" : ""}${numberLabel(delta, definition.type === "number" ? definition.precision : 1)}${comparison.mode === "relative" ? "%" : comparison.mode === "percentage-points" ? " 个百分点" : definition.type === "number" ? ` ${definition.unit}` : ""}`}
                      </span>
                    </span>
                    <span className="text-muted-foreground">
                      {comparison.label}
                    </span>
                  </div>
                )}
              </div>
            )}
            {(invalid ||
              !available ||
              message ||
              definition.description ||
              outside) && (
              <p
                className={`text-sm leading-relaxed ${outside ? "text-warning-text" : "text-muted-foreground"}`}
              >
                {invalid
                  ? message || "数据无效，暂不可用于判断"
                  : !available
                    ? value === null
                      ? "暂无数据"
                      : "数据与定义不匹配"
                    : message ||
                      (outside ? "超出定义范围" : definition.description)}
              </p>
            )}
            {definition.type === "number" &&
              visualization === "trend" &&
              (history ? (
                <TelemetrySparkline
                  history={history}
                  label={definition.label}
                  unit={definition.type === "number" ? definition.unit : ""}
                  precision={
                    definition.type === "number"
                      ? definition.precision
                      : undefined
                  }
                />
              ) : (
                <p className="text-sm text-muted-foreground">暂无历史数据</p>
              ))}
            {numeric &&
              visualization === "range" &&
              definition.type === "number" &&
              (definition.range ? (
                <RangeGauge
                  embedded
                  showValue={false}
                  label={definition.label}
                  value={value}
                  unit={definition.unit}
                  precision={definition.precision}
                  {...definition.range}
                />
              ) : (
                <p className="text-sm text-muted-foreground">未定义范围</p>
              ))}
            {metadata && <div className="text-sm">{metadata}</div>}
          </>
        )}
      </div>
      {!loading && !error && !!secondary?.length && (
        <dl className="flex flex-wrap gap-x-6 gap-y-2 border-t border-border pt-4 text-sm">
          {secondary.map((item) => (
            <div key={item.label} className="flex min-w-0 flex-wrap gap-x-2">
              <dt className="text-muted-foreground">{item.label}</dt>
              <dd className="tabular-nums wrap-anywhere">{item.value}</dd>
            </div>
          ))}
        </dl>
      )}
      <details data-slot="data-card-details" className="text-sm">
        <summary>
          <ChevronRight className="size-4 shrink-0" aria-hidden="true" />
          {kind === "metric" ? "来源与测量定义" : "计算依据与口径"}
        </summary>
        <dl className="grid gap-3 pt-2 @md:grid-cols-2">
          <div className="min-w-0">
            <dt className="text-muted-foreground">标识</dt>
            <dd className="mt-1 font-mono wrap-anywhere">{definition.id}</dd>
          </div>
          {details}
        </dl>
      </details>
    </Panel>
  );
}

import {
  DataCard,
  DataTimestamp,
  DataTimeWindow,
  type DataCardPresentation,
} from "@/components/iot/internal/data-card";
import type {
  CardDefinition,
  CardValue,
} from "@/components/iot/internal/data-card-model";
import { qualityLabels, type Quality } from "@/lib/iot-model";

export type IndicatorDefinition = CardDefinition;
export type IndicatorResult = {
  value: CardValue;
  calculatedAt: number | null;
  window?: { from: number; to: number };
  quality?: Quality;
  reason?: string;
};
export type IndicatorMethod = {
  label: string;
  version?: string;
  inputs?: string[];
};

/** A derived result; computation time, input window and method stay distinct. */
export function IndicatorCard({
  definition,
  result,
  method,
  ...presentation
}: DataCardPresentation & {
  definition: IndicatorDefinition;
  result: IndicatorResult;
  method: IndicatorMethod;
}) {
  return (
    <DataCard
      {...presentation}
      kind="indicator"
      definition={definition}
      value={result.value}
      invalid={result.quality === "bad"}
      message={result.reason}
      metadata={
        result.value === null && result.calculatedAt === null ? null : (
          <div className="space-y-2 text-muted-foreground">
            <div className="flex flex-wrap items-baseline gap-x-2 gap-y-1">
              {result.calculatedAt == null ? (
                <span>计算时间未知</span>
              ) : (
                <>
                  <span>计算于</span>
                  <DataTimestamp at={result.calculatedAt} />
                </>
              )}
              <span
                className={
                  result.quality === "bad"
                    ? "text-destructive"
                    : result.quality !== "good"
                      ? "text-warning-text"
                      : ""
                }
              >
                · {qualityLabels[result.quality ?? "unknown"]}
              </span>
            </div>
            {result.window && (
              <dl className="flex flex-wrap items-baseline gap-x-2 gap-y-1">
                <dt>统计窗口</dt>
                <dd className="min-w-0">
                  <DataTimeWindow {...result.window} />
                </dd>
              </dl>
            )}
          </div>
        )
      }
      details={
        <>
          <div>
            <dt className="text-muted-foreground">计算方法</dt>
            <dd className="mt-1 wrap-anywhere">
              {method.label}
              {method.version && ` · ${method.version}`}
            </dd>
          </div>
          {!!method.inputs?.length && (
            <div className="@md:col-span-2">
              <dt className="text-muted-foreground">输入依据</dt>
              <dd className="mt-1 wrap-anywhere">{method.inputs.join("、")}</dd>
            </div>
          )}
        </>
      }
    />
  );
}
